请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-009

=== 用户原始指令 (query.txt) ===
搞个卡,字叠背景图上,点一下跳充电应用,顺便读日程

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个卡,字叠背景图上,点一下跳充电应用,顺便读日程",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "今日日程列表，按开始时间排序。",
          "sampleValue": [
            {
              "entityId": "sample-calendar-001",
              "title": "产品评审",
              "dtStart": "14:00",
              "dtEnd": "15:00",
              "eventLocation": "3F会议室"
            }
          ],
          "items": [
            {
              "entityId": {
                "type": "string",
                "description": "日程项唯一标识符，用于查看日程详情。",
                "sampleValue": "sample-calendar-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题。",
                "sampleValue": "产品评审"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间，当天日程使用 HH:MM 格式。",
                "sampleValue": "14:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间，当天日程使用 HH:MM 格式。",
                "sampleValue": "15:00"
              },
              "eventLocation": {
                "type": "string",
                "description": "日程发生地点。",
                "sampleValue": "3F会议室"
              }
            }
          ]
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_charge.png",
      "description": "充电/闪电图标，适合低电模式下作为背景视觉锚点或充电入口识别。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合日程管理、日历事件查看和当日安排识别。"
    },
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程图标，适合当下日程和今日安排识别，适合深色或渐变背景上的小图标展示。"
    }
  ]
}

